(2860863, 397127, 15032, '<td valign="top">Great sharpness and DOF.  One of my favorites from the challenge!</td>', 'Great sharpness and DOF.  One of my favorites from the challenge!', '2006-09-24 15:53:28.000000', NULL, 1),
