(2863308, 397369, 57882, '<td valign="top">Fantastic presentation.  All the parts have really come together well here, topped off with excellent lighting.</td>', 'Fantastic presentation.  All the parts have really come together well here, topped off with excellent lighting.', '2006-09-25 13:47:46.000000', NULL, 0),
(2863315, 396003, 64733, '<td valign="top">i had this at a 9.  i loved the concept and the execution.  great use of negative space to add meaning, entriguing depth of field, and good focus on the subject.</td>', 'i had this at a 9.  i loved the concept and the execution.  great use of negative space to add meaning, entriguing depth of field, and good focus on the subject.', '2006-09-25 13:51:58.000000', NULL, 0),
