INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2865278, 395012, 22301, '<td valign="top">Wow I am surprised that you didn''t receive any comments at all. I looked at it for abit and tried to figure out why it didn''t connect. When I look at it, to me it seems like it is a walnut and raisins in sand. Maybe voters who look for 2 seconds thought the same and moved on.  I don''t know much about day lilies but I am unsure if they grow around sand and perhaps the voters thought it was out of place and just moved on with a five.  I have received comments where I realize how broad a range of voters there are in challenges, and choosing a seed that is not easily recognizable and fairly easy to be misinterpeted as something not a seed, would make it difficult for them to begin to understand your message and would think they just don''t get it but it is a good photo and give you a 4, 5, or 6. I hope this helps some. You know you got my respect Doc. Good luck in the future, your photos always have a story and it great to see what your up to.<br/>Joe</td>', 'Wow I am surprised that you didn''t receive any comments at all. I looked at it for abit and tried to figure out why it didn''t connect. When I look at it, to me it seems like it is a walnut and raisins in sand. Maybe voters who look for 2 seconds thought the same and moved on.  I don''t know much about day lilies but I am unsure if they grow around sand and perhaps the voters thought it was out of place and just moved on with a five.  I have received comments where I realize how broad a range of voters there are in challenges, and choosing a seed that is not easily recognizable and fairly easy to be misinterpeted as something not a seed, would make it difficult for them to begin to understand your message and would think they just don''t get it but it is a good photo and give you a 4, 5, or 6. I hope this helps some. You know you got my respect Doc. Good luck in the future, your photos always have a story and it great to see what your up to.Joe', '2006-09-26 04:53:17.000000', NULL, 0),
